suppressPackageStartupMessages(library(data.table))
a<-grep('^--file=',commandArgs(),value=TRUE);root<-dirname(dirname(normalizePath(sub('^--file=','',a[1]))));r<-function(n)fread(file.path(root,n),check.names=FALSE)
x<-r('P41_corrected_cell_feature_matrix.csv');m<-r('P41_cell_annotations.csv');f<-r('P41_feature_annotations.csv');stopifnot(identical(x$cell_id,m$cell_id),identical(names(x)[-1],f$feature_id),!anyDuplicated(m$cell_id),!anyDuplicated(f$feature_id))
y<-copy(x[,-1]);nm<-ifelse(!is.na(f$annotation)&nzchar(f$annotation),paste0(f$annotation,' [',f$feature_id,']'),f$feature_id);setnames(y,nm);out<-cbind(m,y);fwrite(out,file.path(root,'P41_corrected_cell_feature_master_with_annotations.csv'),na='');z<-r('P41_corrected_cell_feature_master_with_annotations.csv');err<-max(abs(as.matrix(z[,..nm])-as.matrix(x[,-1])));stopifnot(err<1e-12);fwrite(data.table(check='annotated_master_readback_every_value',n_cells=nrow(x),n_features=nrow(f),max_abs_difference=err,passed=TRUE),file.path(root,'export_validation.csv'))
